    "titleEn": "Feedback Regulation in Cushing Syndrome",
    "titleAr": "تحليل التغذية الراجعة السلبية في متلازمة كوشينغ",
    "difficulty": "hots",
    "questionEn": "A patient presents with high blood cortisol, hypertension, central obesity, and hyperglycemia. Laboratory tests reveal that ACTH level in blood is undetectable (near zero). The likely diagnosis and underlying feedback mechanism is:",
    "questionAr": "مريض يعاني من ارتفاع شديد في كورتيزول الدم، ارتفاع ضغط الدم، سمنة مركزية، وارتفاع السكر. أظهرت الفحوصات أن مستوى ACTH في دمه منعدم تقريباً. التشخيص المرجح وآلية التغذية الراجعة المفسرة لذلك هي:",
    "optionsEn": [
      "Primary adrenal cortex tumor hypersecreting cortisol, which suppresses pituitary ACTH via negative feedback",
      "Pituitary adenoma hypersecreting ACTH continuously despite high cortisol levels",
      "Hypothalamic failure to produce TRH leading to secondary adrenal overactivity",
      "Congenital absence of aldosterone receptors in renal nephrons"
    ],
    "optionsAr": [
      "ورم أولي في قشرة الغدة الكظرية يفرز الكورتيزول ذاتياً، مما يثبط إفراز هرمون ACTH من النخامية بالتغذية الراجعة السلبية",
      "ورم في الغدة النخامية يفرز ACTH باستمرار متجاهلاً الارتفاع الحاد في مستوى الكورتيزول",
      "فشل في الهيبوثالاموس لإنتاج هرمون TRH مما أدى لفرط نشاط قشرة الكظر الثانوي",
      "غياب خلقي تام لمستقبلات الألدوستيرون في نفرونات الكلى"
    ],
    "correctAnswer": "Primary adrenal cortex tumor hypersecreting cortisol, which suppresses pituitary ACTH via negative feedback",
    "correctIndex": 0,
    "hintEn": "Check whether ACTH is high or low: low ACTH indicates the adrenal cortex is acting autonomously (primary defect).",
