    "teacherTipEn": "Incretin effect = Oral glucose yields greater insulin secretion than IV glucose via GLP-1 / GIP release.",
    "teacherTipAr": "تأثير الإنكريتين = الجلوكوز الفموي يحفز إفراز إنسولين أعلى من الوريدي بفضل هرمونات الأمعاء (GLP-1)."
